message.content:
{
  "description": "The creature is shown in right-facing profile against a plain off-white background, standing on four limbs. The overall body shape, fur, head, ears, hindquarters and tail are those of a large gray wolf, with dense shaggy fur, but the middle of the back is covered by a large dark glossy segmented dome-shaped shell, and the two forelimbs are not wolf legs but thick, heavily armored, jointed limbs ending in large pincer claws. The hind legs remain fur-covered wolf legs with paws, while the front legs are dark bluish-black and olive-green, shiny, and crustacean-like.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated wolf muzzle with a black nose, amber-brown eyes, white and light gray fur around the muzzle and cheeks, darker gray on the forehead and bridge of the nose",
      "where": "at the far right front of the body, in profile facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with gray outer fur and darker interior, with visible inner hair",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "mane / neck fur",
      "looks_like": "thick shaggy ruff of long gray, white and beige fur",
      "where": "around the neck, throat and chest, extending from behind the ears down to the front of the chest and along the underside"
    },
    {
      "part": "legs",
      "looks_like": "four legs total: the two hind legs are slender, fur-covered wolf legs with visible hock joints; the two front legs are thick, jointed, heavily armored crustacean limbs made of overlapping glossy dark bluish-green to black plates with small spines along the rear edges",
      "where": "hind legs at the left rear under the body; front armored legs at the right front under the chest, both pairs extending to the ground"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with light fur, dark claws and pads; front feet are large glossy dark pincer claws with two thick curved opposing fingers and small rounded tubercles near the base",
      "where": "hind paws at the bottom of the hind legs on the ground at left; pincers at the bottom ends of the armored front legs on the ground at right"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy wolf tail covered in dense gray, white and dark guard hairs, with a slightly darker tip",
      "where": "at the far left rear of the body, hanging down behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large domed glossy carapace, dark olive-green to bluish-black with lighter highlights, divided into about five broad transverse segments with a scalloped, spiny margin",
      "where": "covering the dorsal mid-back from just behind the shoulders to above the hips, sitting on top of the fur with its lower edge overlapping the side fur"
    },
    {
      "part": "plates / scales",
      "looks_like": "hard overlapping shiny plates forming both the dorsal shell and the armor on the front legs, with segmented ridges, small pits and spiny projections along the edges",
      "where": "as the surface of the back shell and as stacked rings encasing the entire length of both front limbs down to the pincers"
    },
    {
      "part": "markings / fur coloration",
      "looks_like": "dense fur that is medium to dark gray on the back, sides, head and tail, with creamy white to beige on the belly, inner legs, chest and around the muzzle, and darker gray guard hairs along the back and tail",
      "where": "over the entire wolf-like portion of the body except where covered by the shell and front-leg armor"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "crab"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
